/*
 * A076503  Prime numbers whose squares have square digit-sums.
 * https://oeis.org/A076503
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the n‑th prime p with the property that the digit sum of
 *            p^2 is a perfect square. The sequence is generated by testing
 *            primes in increasing order and storing those that satisfy the
 *            condition
 * Range:     u8 n <= 4, u16 n <= 20, u32 n <= 878, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* ------------------------------------------------------------------ */
/* Dynamic arrays for primes and for the sequence terms.            */
/* ------------------------------------------------------------------ */
static seq_t *prime_list  = NULL;          /* list of primes found           */
static size_t   prime_count = 0, prime_cap = 0;

static seq_t *term_list   = NULL;          /* list of terms of the sequence */
static size_t  term_count  = 0, term_cap   = 0;

/* ------------------------------------------------------------------ */
/* Helper: integer square‑root test for uint64_t sums.                */
/* ------------------------------------------------------------------ */
static inline bool is_square_uint64(uint64_t x)
{
    for (uint64_t r = 0; r * r <= x; ++r)
        if (r * r == x) return true;
    return false;
}

/* ------------------------------------------------------------------ */
/* Helper: test whether a prime p satisfies the digit‑sum‑square     */
/* property.                                                           */
/* ------------------------------------------------------------------ */
static inline bool ok_prime(seq_t p)
{
    seq_t sq = p * p;                /* compute square of the prime */
    uint64_t sum = 0;
    seq_t temp = sq;
    while (temp != 0) {
        sum += (uint64_t)(temp % (seq_t)10);
        temp /= (seq_t)10;
    }
    return is_square_uint64(sum);
}

/* ------------------------------------------------------------------ */
/* Append to dynamic array of primes.                                 */
/* ------------------------------------------------------------------ */
static inline void add_prime(seq_t p)
{
    if (prime_count == prime_cap) {
        prime_cap = prime_cap ? prime_cap * 2 : 128;
        prime_list = (seq_t*)realloc(prime_list, prime_cap * sizeof(seq_t));
        if (!prime_list) abort();
    }
    prime_list[prime_count++] = p;
}

/* ------------------------------------------------------------------ */
/* Append to dynamic array of terms.                                  */
/* ------------------------------------------------------------------ */
static inline void add_term(seq_t p)
{
    if (term_count == term_cap) {
        term_cap = term_cap ? term_cap * 2 : 128;
        term_list = (seq_t*)realloc(term_list, term_cap * sizeof(seq_t));
        if (!term_list) abort();
    }
    term_list[term_count++] = p;
}

/* ------------------------------------------------------------------ */
/* Prime test for a value.  Uses the current list of known primes.    */
/* ------------------------------------------------------------------ */
static inline bool is_prime_candidate(seq_t n)
{
    if (n < 2) return false;
    for (size_t i = 0; i < prime_count; ++i) {
        seq_t p = prime_list[i];
        /* stop if p^2 > n */
        seq_t pp = p * p;
        if (pp > n) break;
        if ((n % p) == 0) return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Generate terms until at least n terms are available.  If n is small,   */
/* this finishes quickly; otherwise it keeps generating primes.       */
/* ------------------------------------------------------------------ */
static void ensure_terms(idx_t n)
{
    if (term_count >= (size_t)n) return;

    /* initialise prime list with 2,3 if empty */
    if (prime_count == 0) {
        add_prime((seq_t)2);
        add_prime((seq_t)3);
    }

    /* add the initial 2 and 3 to the sequence if they satisfy the property */
    if (term_count == 0) {          /* term_list may be empty initially */
        if (ok_prime((seq_t)2)) add_term((seq_t)2);
        if (ok_prime((seq_t)3)) add_term((seq_t)3);
    }

    /* start checking from the last odd candidate after 3 */
    static seq_t candidate = 5;     /* static to keep state between calls */

    while (term_count < (size_t)n) {
        /* test candidate for primality */
        if (is_prime_candidate(candidate)) {
            add_prime(candidate);
            if (ok_prime(candidate)) add_term(candidate);
        }
        /* next odd candidate */
        candidate += 2;
    }
}

/* ------------------------------------------------------------------ */
/* Public function required by the framework.                          */
/* ------------------------------------------------------------------ */
seq_t a(idx_t n)                    /* n ≥ 1, a(1) is the first term (= 2) */
{
    if (n == 0) return 0;           /* undefined for n = 0, return 0 */

    ensure_terms(n);
    return term_list[(size_t)n - 1];
}
